export const RATES: Record<string, number> = { CA: 0.0725, NY: 0.04, TX: 0.0625, OR: 0 };

export function lineTax(price: number, qty: number, state: string): number {
  const rate = RATES[state] ?? 0;
  return Math.round(price * qty * rate * 100) / 100;
}

export function calculateTax(items: { price: number; qty: number; taxable: boolean }[], state: string): number {
  return items.filter(i => i.taxable).reduce((s, i) => s + lineTax(i.price, i.qty, state), 0);
}

import { calculateTax } from './tax';

const item = (price: number, taxable = true) => ({ price, qty: 1, taxable });

it('CA rate applied', () => expect(calculateTax([item(100)], 'CA')).toBe(7.25));
it('OR has no tax', () => expect(calculateTax([item(100)], 'OR')).toBe(0));
it('non-taxable items skipped', () => expect(calculateTax([item(100, false)], 'CA')).toBe(0));
it('rounds half up per line item', () => expect(calculateTax([item(6)], 'CA')).toBe(0.44));

